$ErrorActionPreference = 'Stop'
$base = "$env:TEMP\claude\us_upr_xlsx"

# --- shared strings ---
[xml]$ss = Get-Content "$base\xl\sharedStrings.xml" -Raw -Encoding UTF8
$ns = @{ x = 'http://schemas.openxmlformats.org/spreadsheetml/2006/main' }
$shared = New-Object System.Collections.Generic.List[string]
foreach ($si in $ss.sst.si) {
    if ($si.t -is [string]) {
        $shared.Add([string]$si.t)
    } elseif ($si.t.'#text') {
        $shared.Add([string]$si.t.'#text')
    } else {
        # rich text runs
        $sb = ''
        foreach ($r in $si.r) { $sb += [string]$r.t.'#text'; if ($r.t -is [string]) { $sb += [string]$r.t } }
        $shared.Add($sb)
    }
}
Write-Host "shared strings: $($shared.Count)"

# --- sheet ---
[xml]$sheet = Get-Content "$base\xl\worksheets\sheet1.xml" -Raw -Encoding UTF8

function Get-ColLetter([string]$ref) {
    ($ref -replace '[0-9]', '')
}

$rows = @()
foreach ($row in $sheet.worksheet.sheetData.row) {
    $cells = @{}
    foreach ($c in $row.c) {
        $col = Get-ColLetter $c.r
        $val = $null
        if ($c.t -eq 's') {
            $val = $shared[[int]$c.v]
        } elseif ($c.t -eq 'inlineStr') {
            $val = [string]$c.is.t
        } elseif ($null -ne $c.v) {
            $val = [string]$c.v
        }
        $cells[$col] = $val
    }
    $rows += ,$cells
}
Write-Host "rows: $($rows.Count)"

# header from row 1
$headers = @{}
foreach ($k in $rows[0].Keys) { $headers[$k] = $rows[0][$k] }

$out = @()
for ($i = 1; $i -lt $rows.Count; $i++) {
    $obj = [ordered]@{}
    foreach ($k in ($headers.Keys | Sort-Object)) {
        $obj[$headers[$k]] = $rows[$i][$k]
    }
    $out += [pscustomobject]$obj
}

$out | ConvertTo-Json -Depth 4 | Set-Content "$env:TEMP\claude\us_upr_rows.json" -Encoding UTF8
Write-Host "wrote $($out.Count) data rows to us_upr_rows.json"

# quick summaries
Write-Host "`n-- Reccomending Body --"
$out | Group-Object 'Reccomending Body' | Select-Object Count,Name | Format-Table -Auto | Out-String | Write-Host
Write-Host "-- UPR Position --"
$out | Group-Object 'UPR Position' | Select-Object Count,Name | Format-Table -Auto | Out-String | Write-Host
Write-Host "-- Document Symbol --"
$out | Group-Object 'Document Symbol' | Select-Object Count,Name | Format-Table -Auto | Out-String | Write-Host
Write-Host "-- UPR Session --"
$out | Group-Object 'UPR Session' | Select-Object Count,Name | Format-Table -Auto | Out-String | Write-Host
Write-Host "-- Document Publication Date --"
$out | Group-Object 'Document Publication Date' | Select-Object Count,Name | Format-Table -Auto | Out-String | Write-Host
Write-Host "`n-- first row sample --"
$out[0] | Format-List | Out-String | Write-Host

