import sys, zipfile, re
from xml.etree import ElementTree as ET

path = sys.argv[1]
W = "{http://schemas.openxmlformats.org/wordprocessingml/2006/main}"

with zipfile.ZipFile(path) as zf:
    names = zf.namelist()
    xml = zf.read("word/document.xml").decode("utf-8", "replace")

root = ET.fromstring(xml)

def para_text(p):
    return "".join(t.text or "" for t in p.iter(W + "t"))

def walk(el, depth=0):
    for child in el:
        tag = child.tag
        if tag == W + "p":
            txt = para_text(child).strip()
            # heading style?
            style = child.find(f"{W}pPr/{W}pStyle")
            sname = style.get(W + "val") if style is not None else ""
            prefix = f"[{sname}] " if sname and "eading" in sname else ""
            if txt:
                print(prefix + txt)
        elif tag == W + "tbl":
            for row in child.findall(W + "tr"):
                cells = []
                for tc in row.findall(W + "tc"):
                    ctext = " ".join(para_text(p).strip() for p in tc.findall(W + "p"))
                    cells.append(ctext.strip())
                print(" | ".join(cells))
            print("---END TABLE---")
        else:
            walk(child, depth + 1)

body = root.find(W + "body")
walk(body)

