cd "C:/Users/rolan/AppData/Local/Temp/claude" && export PYTHONIOENCODING=utf-8 && PY="/c/Users/rolan/AppData/Local/Programs/Python/Python312/python.exe" && "$PY" - <<'EOF'
import urllib.request, urllib.parse, ssl, re, subprocess, time, os
ctx=ssl.create_default_context(); ctx.check_hostname=False; ctx.verify_mode=ssl.CERT_NONE
UA={'User-Agent':'Mozilla/5.0'}
syms=[l.strip() for l in open('syms.txt') if l.strip()]
os.makedirs('fu_all',exist_ok=True)
ok=0; miss=[]
for s in syms:
    tag=s.replace('CCPR/C/','').replace('/','_').replace('.','')
    out=f'fu_all/{tag}.txt'
    if os.path.exists(out) and os.path.getsize(out)>500:
        ok+=1; continue
    enc=urllib.parse.quote(s,safe='')
    u=f"https://tbinternet.ohchr.org/_layouts/15/treatybodyexternal/Download.aspx?symbolno={enc}&Lang=en"
    try:
        hp=urllib.request.urlopen(urllib.request.Request(u,headers=UA),context=ctx,timeout=90).read().decode('utf-8','replace')
    except Exception as e:
        miss.append((s,'viewer',str(e)[:60])); continue
    pdfs=re.findall(r'href="(https://docstore\.ohchr\.org/SelfServices/FilesHandler\.ashx\?enc=[^"]+)"[^>]*>\s*<img[^>]+pdf\.gif',hp)
    if not pdfs:
        miss.append((s,'nolinks','')); continue
    got=False
    for link in pdfs[:3]:
        try:
            b=urllib.request.urlopen(urllib.request.Request(link,headers=UA),context=ctx,timeout=120).read()
        except Exception as e:
            continue
        if b[:4]!=b'%PDF': continue
        open(f'fu_all/{tag}.pdf','wb').write(b)
        subprocess.run(["pdftotext","-nopgbrk",f'fu_all/{tag}.pdf',out],capture_output=True)
        try: txt=open(out,encoding='utf-8',errors='replace').read()
        except: txt=''
        if re.search(r'Original:\s*English',txt) or 'follow-up' in txt.lower():
            got=True; ok+=1; break
    if not got: miss.append((s,'noEN',''))
    time.sleep(0.4)
print("downloaded/cached:",ok,"/",len(syms))
print("MISSES:")
for m in miss: print("  ",m)
EOF

