      documentation for the ${esc(m.review)} review.</p>
    ${m.headline ? `<p class="lead">${esc(m.headline)}</p>` : ""}
    <p class="note"><strong>Sources.</strong> ${m.sources.map(esc).join(" · ")}</p>
    ${themes}`;
}

